def is_prime(n):
    if n <= 1: return False
    for i in range(2, int(n**0.5)+1):
        if n % i == 0: return False
    return True

def dedup(lst):
    seen = set()
    result = []
    for x in lst:
        if x not in seen:
            seen.add(x)
            result.append(x)
    return result

def is_valid(s):
    stack = []
    pairs = {')':'(', ']':'[', '}':'{'}
    for c in s:
        if c in '([{': stack.append(c)
        elif c in pairs:
            if not stack or stack[-1] != pairs[c]: return False
            stack.pop()
    return not stack

def gcd(a, b):
    a, b = abs(a), abs(b)
    while b:
        a, b = b, a % b
    return a

def is_palindrome(s):
    s = s.lower()
    return s == s[::-1]

def find_max(lst):
    if not lst: return None
    m = lst[0]
    for x in lst:
        if x > m: m = x
    return m

def fib(n):
    if n <= 1: return n
    a, b = 0, 1
    for _ in range(n-1):
        a, b = b, a+b
    return b

def find_min(lst):
    if not lst: return None
    m = lst[0]
    for x in lst:
        if x < m: m = x
    return m

def is_sorted(lst):
    for i in range(len(lst)-1):
        if lst[i] > lst[i+1]: return False
    return True

def average(lst):
    if not lst: return 0
    return sum(lst) / len(lst)

def most_common(s):
    if not s: return None
    counts = {}
    for c in s:
        counts[c] = counts.get(c, 0) + 1
    return max(counts, key=counts.get)

def second_largest(lst):
    unique = sorted(set(lst), reverse=True)
    return unique[1] if len(unique) > 1 else None

def first_unique(s):
    counts = {}
    for c in s:
        counts[c] = counts.get(c, 0) + 1
    for c in s:
        if counts[c] == 1: return c
    return None

def is_palindrome_alnum(s):
    cleaned = ''.join(c.lower() for c in s if c.isalnum())
    return cleaned == cleaned[::-1]

def bubble_sort(lst):
    arr = lst[:]
    n = len(arr)
    for i in range(n):
        for j in range(n-i-1):
            if arr[j] > arr[j+1]:
                arr[j], arr[j+1] = arr[j+1], arr[j]
    return arr

def roman_to_int(s):
    values = {'I':1,'V':5,'X':10,'L':50,'C':100,'D':500,'M':1000}
    total = 0
    for i, c in enumerate(s):
        if i + 1 < len(s) and values[c] < values[s[i+1]]:
            total -= values[c]
        else:
            total += values[c]
    return total

def two_sum(lst, target):
    seen = {}
    for i, x in enumerate(lst):
        if target - x in seen:
            return [seen[target-x], i]
        seen[x] = i
    return []

def merge_sorted(a, b):
    result = []
    i = j = 0
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            result.append(a[i]); i += 1
        else:
            result.append(b[j]); j += 1
    result.extend(a[i:])
    result.extend(b[j:])
    return result

def majority_element(lst):
    counts = {}
    for x in lst:
        counts[x] = counts.get(x, 0) + 1
        if counts[x] > len(lst) // 2: return x
    return None

def longest_increasing(lst):
    if not lst: return 0
    max_len = 1
    cur = 1
    for i in range(1, len(lst)):
        if lst[i] > lst[i-1]:
            cur += 1
            max_len = max(max_len, cur)
        else:
            cur = 1
    return max_len
